<?php require_once App\Core\Config::$DIR_BASE . '/App/Views/SBAdmin/Contract/ContractViewHelpers.php'; ?>
<div class="d-flex justify-content-between mb-3"><div><?= ctr_status($data['FormData']['Status'] ?? ''); ?> <strong class="ml-2"><?= ctr_e($data['ContractId']); ?></strong><div class="small text-muted mt-1"><?= ctr_e($data['FormData']['Description'] ?? ''); ?><?= (($data['FormData']['Client'] ?? '') !== '') ? ' - ' . ctr_e($data['FormData']['Client']) : ''; ?></div></div><div><a class="btn btn-outline-primary" href="/Contract/ContractItem/Index/<?= rawurlencode($data['ContractId']); ?>">Itens</a><a class="btn btn-outline-primary" href="/Contract/ContractSignatory/Index/<?= rawurlencode($data['ContractId']); ?>">Signatários</a></div></div>
<div class="row"><div class="col-lg-6"><h5>Itens</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Descrição</th><th>Total</th><th>Franquia</th></tr></thead><tbody><?php foreach ($data['Items'] as $row): ?><tr><td><?= ctr_e($row['Description']); ?></td><td>R$ <?= ctr_money($row['LineTotal']); ?></td><td><?= ctr_e($row['UsageLimit']); ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-lg-6"><h5>Signatários</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Usuário</th><th>Papel</th><th>Data</th></tr></thead><tbody><?php foreach ($data['Signatories'] as $row): ?><tr><td><?= ctr_e($row['UserId']); ?></td><td><?= ctr_e($row['Role']); ?></td><td><?= ctr_date($row['SignedAt']); ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<h5>Extrato de consumo</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Item</th><th>Movimento</th><th>Saldo</th><th>Data</th></tr></thead><tbody><?php foreach ($data['Ledger'] as $row): ?><tr><td><?= ctr_e($row['ItemDescription']); ?></td><td><?= (int) $row['ConsumedQuantity']; ?></td><td><?= (int) $row['CurrentBalance']; ?></td><td><?= ctr_date($row['ConsumedAt']); ?></td></tr><?php endforeach; ?></tbody></table></div>
